CREATE TABLE IF NOT EXISTS category_catalog (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  universe TEXT NOT NULL CHECK (universe IN ('MARKET','SAVEURS','EVASION')),
  slug TEXT NOT NULL,
  name TEXT NOT NULL,
  description TEXT NOT NULL DEFAULT '',
  icon TEXT NOT NULL DEFAULT '•',
  parent_slug TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  active BOOLEAN NOT NULL DEFAULT TRUE,
  filters JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  UNIQUE (universe, slug)
);

CREATE INDEX IF NOT EXISTS idx_category_catalog_universe_order
  ON category_catalog(universe, active, sort_order, name);
CREATE INDEX IF NOT EXISTS idx_category_catalog_parent
  ON category_catalog(universe, parent_slug, sort_order);


