ON CONFLICT (universe, slug) DO UPDATE SET
  name=EXCLUDED.name,
  description=EXCLUDED.description,
  icon=EXCLUDED.icon,
  sort_order=EXCLUDED.sort_order,
  filters=EXCLUDED.filters,
  updated_at=NOW();

ON CONFLICT (universe, slug) DO UPDATE SET
  name=EXCLUDED.name,
  description=EXCLUDED.description,
  parent_slug=EXCLUDED.parent_slug,
  sort_order=EXCLUDED.sort_order,
  updated_at=NOW();
